def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    total_thousand_acres = v1 + v2 + v3
    total_million_acres = total_thousand_acres / 1000
    return {
        "value": total_million_acres,
        "trace": {
            "total_thousand_acres": total_thousand_acres,
            "output_meta": {
                "currency": None,
                "scale": "million",
                "unit": "acres"
            }
        }
    }
